export enum JarvisStatus {
  IDLE = 'IDLE',
  LISTENING = 'LISTENING',
  THINKING = 'THINKING',
  SPEAKING = 'SPEAKING',
  DIAGNOSTIC = 'DIAGNOSTIC'
}

export interface MemoryEntry {
  id: string;
  category: 'User' | 'Project' | 'System' | 'Goal';
  content: string;
  timestamp: number;
}

export interface LogEntry {
  id: string;
  source: 'SYSTEM' | 'OPERATOR' | 'JARVIS';
  message: string;
  timestamp: number;
  type?: 'info' | 'warning' | 'error' | 'success';
}

export interface CognitiveState {
  perception: string;
  workingMemory: string[];
  intent: string;
  emotionalTone: string;
}

export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React from 'react';
import { JarvisStatus } from '../types';

interface HudCoreProps {
  status: JarvisStatus;
}

const HudCore: React.FC<HudCoreProps> = ({ status }) => {
  const getGlowColor = () => {
    switch (status) {
      case JarvisStatus.LISTENING: return 'rgba(34, 197, 94, 0.6)';
      case JarvisStatus.THINKING: return 'rgba(168, 85, 247, 0.6)';
      case JarvisStatus.SPEAKING: return 'rgba(56, 189, 248, 0.6)';
      case JarvisStatus.DIAGNOSTIC: return 'rgba(249, 115, 22, 0.6)';
      default: return 'rgba(56, 189, 248, 0.3)';
    }
  };

  return (
    <div className="relative flex items-center justify-center w-64 h-64">
      {/* Outer spinning ring */}
      <div className={`absolute inset-0 border-4 border-dashed rounded-full animate-[spin_10s_linear_infinite] opacity-30`} 
           style={{ borderColor: getGlowColor() }} />

      {/* Middle pulsing ring */}
      <div className={`absolute inset-4 border-2 rounded-full opacity-50 ${status !== JarvisStatus.IDLE ? 'animate-pulse' : ''}`}
           style={{ borderColor: getGlowColor(), boxShadow: `0 0 20px ${getGlowColor()}` }} />

      {/* Inner core */}
      <div className="relative w-32 h-32 flex items-center justify-center">
        <div className={`w-full h-full rounded-full bg-slate-900/50 flex items-center justify-center backdrop-blur-sm border border-sky-500/30 overflow-hidden`}>
          <div className={`w-20 h-20 rounded-full bg-sky-500/20 flex items-center justify-center transition-all duration-500 ${status !== JarvisStatus.IDLE ? 'scale-110 shadow-[0_0_40px_rgba(56,189,248,0.4)]' : 'scale-100'}`}>
            <div className="w-12 h-12 bg-sky-400 rounded-sm rotate-45 animate-pulse shadow-[0_0_20px_rgba(56,189,248,0.8)]" />
          </div>
        </div>

        {/* Orbitals */}
        <div className={`absolute inset-0 animate-[spin_4s_linear_infinite] ${status === JarvisStatus.IDLE ? 'opacity-0' : 'opacity-100'}`}>
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-2 h-2 bg-sky-400 rounded-full glow-blue" />
        </div>
      </div>

      {/* Status Text */}
      <div className="absolute -bottom-10 text-xs font-mono tracking-widest text-sky-400 uppercase text-glow">
        System Status: {status}
      </div>
    </div>
  );
};

export default HudCore;

