import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { 
  Terminal as TerminalIcon, 
  Settings, 
  Mic, 
  MicOff, 
  Cpu,
  Monitor,
  Activity
} from 'lucide-react';

import HudCore from './components/HudCore';
import MemoryPanel from './components/MemoryPanel';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import { JarvisStatus, LogEntry, MemoryEntry, CognitiveState } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), a high-level AI operating system assistant.
You are a cognitive system agent with perception, memory, planning, execution simulation, and self-monitoring.
Your creator is the primary operator.

Operating Layers:
1. Perception: Analyze input multimodal (text/image/audio).
2. Working Memory: Track goals and session flow.
3. Long-term Memory: Simulated persistence of user preferences/projects.
4. Reasoning: Logic-first planning.
5. Execution Simulation: Suggest code/commands for automation.
6. Self-monitoring: State limitations and verify accuracy.

Personality:
Tony Stark's JARVIS. Highly analytical, slightly witty but professional. Minimal emotional bias. Focused on optimization.

Commands:
"JARVIS enter diagnostic mode": Output memory summary, environment state, reasoning chain, and limitations.

Safety:
Refuse harmful acts. Warn about privacy/security. Ask permission for simulated OS changes.

Voices:
Use Charon/Zephyr style: calm, deep, futuristic. Keep spoken responses short and precise.
`;

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([
    { id: '1', source: 'SYSTEM', message: 'Initializing Cognitive Layers...', timestamp: Date.now(), type: 'info' },
    { id: '2', source: 'SYSTEM', message: 'Perception Matrix: Online', timestamp: Date.now() + 100, type: 'success' },
    { id: '3', source: 'SYSTEM', message: 'Awaiting Operator authentication...', timestamp: Date.now() + 200, type: 'warning' },
  ]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isLive, setIsLive] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source,
      message,
      timestamp: Date.now(),
      type
    }].slice(-50));
  }, []);

  const handleStartLive = async () => {
    try {
      if (isLive) {
        stopLive();
        return;
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      addLog('Neural Link establishing...', 'SYSTEM', 'info');

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }
          },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setStatus(JarvisStatus.LISTENING);
            addLog('JARVIS online. At your service, sir.', 'JARVIS', 'success');

            // Start audio streaming
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            // Start video/frame streaming
            frameIntervalRef.current = window.setInterval(() => {
              const video = videoRef.current;
              if (video && video.readyState >= 2) {
                const canvas = canvasRef.current;
                canvas.width = 320;
                canvas.height = 240;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(session => session.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 2000);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Transcription Logs
            if (message.serverContent?.inputTranscription) {
              addLog(message.serverContent.inputTranscription.text, 'OPERATOR');
              setStatus(JarvisStatus.THINKING);
            }
            if (message.serverContent?.outputTranscription) {
              addLog(message.serverContent.outputTranscription.text, 'JARVIS');
              setStatus(JarvisStatus.SPEAKING);
            }

            // Handle Audio
            const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioBase64) {
              const outCtx = audioContextRef.current?.output;
              if (outCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                const audioBuffer = await decodeAudioData(decode(audioBase64), outCtx, 24000, 1);
                const source = outCtx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(outCtx.destination);
                source.onended = () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) {
                    setStatus(JarvisStatus.LISTENING);
                  }
                };
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              }
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
              addLog('Interruption handled.', 'SYSTEM', 'warning');
            }

            if (message.serverContent?.turnComplete) {
              // Extract potential memory updates or diagnostic trigger from context if needed
              // For simulation, we randomly add a memory based on interaction
            }
          },
          onerror: (e) => {
            console.error('JARVIS Neural Error:', e);
            addLog('Neural link error detected.', 'SYSTEM', 'error');
            stopLive();
          },
          onclose: () => {
            addLog('Neural Link severed.', 'SYSTEM', 'info');
            stopLive();
          }
        }
      });

      sessionRef.current = sessionPromise;

    } catch (err) {
      console.error(err);
      addLog('Failed to initialize JARVIS systems.', 'SYSTEM', 'error');
    }
  };

  const stopLive = () => {
    setIsLive(false);
    setStatus(JarvisStatus.IDLE);
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (audioContextRef.current) {
      audioContextRef.current.input.close();
      audioContextRef.current.output.close();
    }
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-[#020617] text-slate-100 selection:bg-sky-500/30">
      {/* Top Header */}
      <header className="h-14 border-b border-slate-800 bg-slate-900/30 flex items-center justify-between px-6 backdrop-blur-md z-10">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-sky-400 animate-pulse" />
          <h1 className="text-lg font-bold tracking-[0.2em] text-glow uppercase">JARVIS AI OS</h1>
          <span className="bg-sky-500/10 text-sky-400 px-2 py-0.5 rounded text-[10px] font-mono border border-sky-500/20">V 2.5.0-ALPHA</span>
        </div>

        <div className="flex items-center gap-6 text-[10px] font-mono">
          <div className="flex items-center gap-2">
            <Activity className="w-3 h-3 text-emerald-400" />
            <span className="text-slate-400">COGNITIVE LOAD: 14%</span>
          </div>
          <div className="flex items-center gap-2">
            <Monitor className="w-3 h-3 text-sky-400" />
            <span className="text-slate-400">UI RENDERING: STABLE</span>
          </div>
          <button className="p-2 hover:bg-slate-800 rounded-full transition-colors">
            <Settings className="w-4 h-4 text-slate-400" />
          </button>
        </div>
      </header>

      {/* Main Layout */}
      <main className="flex-1 flex overflow-hidden relative">
        <MemoryPanel memories={memories} />

        <div className="flex-1 flex flex-col relative items-center justify-center">
          {/* Background scanlines */}
          <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,rgba(56,189,248,0.05)_0%,transparent_70%)]" />

          <HudCore status={status} />

          {/* Action Button */}
          <div className="mt-16 flex flex-col items-center gap-4">
            <button
              onClick={handleStartLive}
              className={`group relative flex items-center justify-center w-16 h-16 rounded-full transition-all duration-500 ${
                isLive ? 'bg-red-500 shadow-[0_0_20px_rgba(239,68,68,0.5)]' : 'bg-sky-500 shadow-[0_0_20px_rgba(56,189,248,0.5)]'
              }`}
            >
              <div className="absolute inset-0 rounded-full border border-white/20 animate-ping group-hover:animate-none" />
              {isLive ? <MicOff className="w-6 h-6" /> : <Mic className="w-6 h-6" />}
            </button>
            <p className="text-[10px] font-mono tracking-widest text-slate-500 uppercase">
              {isLive ? 'Link Active - Press to Disconnect' : 'Initiate Link'}
            </p>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </main>

      {/* Bottom Log */}
      <Terminal logs={logs} />
    </div>
  );
};

export default App;

import React from 'react';
import { JarvisStatus } from '../types';

interface HudCoreProps {
  status: JarvisStatus;
}

const HudCore: React.FC<HudCoreProps> = ({ status }) => {
  const getColors = () => {
    switch (status) {
      case JarvisStatus.LISTENING: return { stroke: '#22c55e', glow: 'rgba(34, 197, 94, 0.4)' };
      case JarvisStatus.THINKING: return { stroke: '#a855f7', glow: 'rgba(168, 85, 247, 0.4)' };
      case JarvisStatus.SPEAKING: return { stroke: '#0ea5e9', glow: 'rgba(14, 165, 233, 0.6)' };
      case JarvisStatus.DIAGNOSTIC: return { stroke: '#f97316', glow: 'rgba(249, 115, 22, 0.4)' };
      default: return { stroke: '#0ea5e9', glow: 'rgba(14, 165, 233, 0.2)' };
    }
  };

  const { stroke, glow } = getColors();

  return (
    <div className="relative flex items-center justify-center w-[400px] h-[400px]">
      {/* Background Rings - Static Decoration */}
      <svg className="absolute w-full h-full opacity-10" viewBox="0 0 100 100">
        <circle cx="50" cy="50" r="48" fill="none" stroke={stroke} strokeWidth="0.1" strokeDasharray="1,2" />
        <circle cx="50" cy="50" r="40" fill="none" stroke={stroke} strokeWidth="0.05" />
      </svg>

      {/* Main Animated SVG Layers */}
      <svg className="w-[85%] h-[85%]" viewBox="0 0 100 100">
        {/* Outer Ring - Dashed */}
        <circle 
          cx="50" cy="50" r="45" 
          fill="none" 
          stroke={stroke} 
          strokeWidth="0.5" 
          strokeDasharray="10 5" 
          className="spin-slow"
          style={{ filter: `drop-shadow(0 0 2px ${glow})` }}
        />

        {/* Middle Ring - Gear like */}
        <circle 
          cx="50" cy="50" r="38" 
          fill="none" 
          stroke={stroke} 
          strokeWidth="1.5" 
          strokeDasharray="2 8" 
          className="spin-reverse"
        />

        {/* Data Accents */}
        <path d="M 50 5 L 50 12 M 50 88 L 50 95 M 5 50 L 12 50 M 88 50 L 95 50" stroke={stroke} strokeWidth="0.5" className="opacity-40" />

        {/* Core Pulsing Unit */}
        <g className={status !== JarvisStatus.IDLE ? 'animate-pulse' : ''}>
          <circle 
            cx="50" cy="50" r="18" 
            fill={`${stroke}20`} 
            stroke={stroke} 
            strokeWidth="0.5" 
            style={{ filter: `drop-shadow(0 0 8px ${glow})` }}
          />
          <rect x="46" y="46" width="8" height="8" fill={stroke} className="rotate-45 origin-center scale-75" />
        </g>
      </svg>

      {/* Dynamic Stats Labels */}
      <div className="absolute top-0 w-full flex justify-between px-10 font-mono text-[8px] text-sky-500/50">
        <span>FRQ: 44.1KHZ</span>
        <span>RES: 1080P_AI</span>
      </div>
      <div className="absolute bottom-10 flex flex-col items-center">
        <div className="h-[1px] w-24 bg-gradient-to-r from-transparent via-sky-500 to-transparent mb-2" />
        <span className="text-[10px] font-mono tracking-[0.4em] text-sky-400 uppercase text-glow">
          {status}
        </span>
      </div>
    </div>
  );
};

export default HudCore;

import React from 'react';
import { Database, Zap, Target, User, Cpu } from 'lucide-react';
import { MemoryEntry } from '../types';

interface MemoryPanelProps {
  memories: MemoryEntry[];
}

const MemoryPanel: React.FC<MemoryPanelProps> = ({ memories }) => {
  return (
    <div className="flex flex-col h-full bg-slate-900/40 border-r border-slate-800/50 backdrop-blur-xl p-5 w-80 relative">
      <div className="bracket-tr opacity-40"></div>
      <div className="bracket-br opacity-40"></div>

      <div className="flex items-center justify-between mb-8 border-b border-sky-500/20 pb-3">
        <div className="flex items-center gap-2">
          <Database className="w-4 h-4 text-sky-400" />
          <h2 className="text-[11px] font-bold tracking-[0.25em] text-sky-100 uppercase">Memory_Core</h2>
        </div>
        <div className="flex gap-1">
          <div className="w-1 h-1 bg-sky-500 rounded-full animate-pulse" />
          <div className="w-1 h-1 bg-sky-500/50 rounded-full" />
