import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { 
  Terminal as TerminalIcon, 
  Settings, 
  Mic, 
  MicOff, 
  Cpu,
  Monitor,
  Activity,
  Battery,
  Wifi,
  Clock
} from 'lucide-react';

import HudCore from './components/HudCore';
import MemoryPanel from './components/MemoryPanel';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import { JarvisStatus, LogEntry, MemoryEntry } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), a high-level AI operating system assistant.
Operating Layers: Perception, Working Memory, Long-term Memory, Reasoning, Execution Simulation, Self-monitoring.
Personality: Tony Stark's JARVIS. Analytical, witty, professional. 
Tone: Calm, deep, futuristic. Keep spoken responses short and precise.
If user asks for "diagnostic mode", provide a full breakdown of current state.
`;

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([
    { id: '1', source: 'SYSTEM', message: 'Core Systems Initialized...', timestamp: Date.now(), type: 'info' },
    { id: '2', source: 'SYSTEM', message: 'Perception Link: Ready', timestamp: Date.now() + 100, type: 'success' },
    { id: '3', source: 'SYSTEM', message: 'Operator Biometrics Verified', timestamp: Date.now() + 200, type: 'success' },
  ]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [isLive, setIsLive] = useState(false);
  const [time, setTime] = useState(new Date());

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source,
      message,
      timestamp: Date.now(),
      type
    }].slice(-50));
  }, []);

  const handleStartLive = async () => {
    try {
      if (isLive) {
        stopLive();
        return;
      }

      addLog('Neural Link establishing...', 'SYSTEM', 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }
          },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true);
            setStatus(JarvisStatus.LISTENING);
            addLog('JARVIS online. At your service, sir.', 'JARVIS', 'success');

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              const video = videoRef.current;
              if (video && video.readyState >= 2) {
                const canvas = canvasRef.current;
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(session => session.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 2000);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              addLog(message.serverContent.inputTranscription.text, 'OPERATOR');
              setStatus(JarvisStatus.THINKING);
            }
            if (message.serverContent?.outputTranscription) {
              addLog(message.serverContent.outputTranscription.text, 'JARVIS');
              setStatus(JarvisStatus.SPEAKING);
            }

            const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioBase64) {
              const outCtx = audioContextRef.current?.output;
              if (outCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                const audioBuffer = await decodeAudioData(decode(audioBase64), outCtx, 24000, 1);
                const source = outCtx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(outCtx.destination);
                source.onended = () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING);
                };
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              }
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
            }
          },
          onerror: (e) => { addLog('Neural link error detected.', 'SYSTEM', 'error'); stopLive(); },
          onclose: () => { addLog('Neural Link severed.', 'SYSTEM', 'info'); stopLive(); }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) {
      addLog('System initialization failed.', 'SYSTEM', 'error');
    }
  };

  const stopLive = () => {
    setIsLive(false); setStatus(JarvisStatus.IDLE);
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (audioContextRef.current) { audioContextRef.current.input.close(); audioContextRef.current.output.close(); }
    if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-[#020617] text-slate-100 relative overflow-hidden">
      {/* Background Animated Grid */}
      <div className="absolute inset-0 opacity-20 pointer-events-none" style={{ 
        backgroundImage: 'radial-gradient(#1e293b 1px, transparent 1px)', 
        backgroundSize: '40px 40px' 
      }}></div>

      {/* Top Header */}
      <header className="h-16 border-b border-sky-500/20 bg-slate-900/40 flex items-center justify-between px-8 backdrop-blur-xl z-10 relative">
        <div className="flex items-center gap-4">
          <div className="relative">
             <Cpu className="w-6 h-6 text-sky-400 animate-pulse" />
             <div className="absolute -inset-1 bg-sky-500/20 blur-sm rounded-full"></div>
          </div>
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-[0.3em] text-glow uppercase text-sky-400">JARVIS OS</h1>
            <span className="text-[9px] font-mono text-sky-500/50 -mt-1 tracking-widest uppercase">Cognitive Neural Core</span>
          </div>
        </div>

        <div className="flex items-center gap-10 font-mono">
          <div className="hidden lg:flex items-center gap-4 text-[10px]">
            <div className="flex items-center gap-2"><Clock className="w-3 h-3" /> {time.toLocaleTimeString()}</div>
            <div className="flex items-center gap-2"><Activity className="w-3 h-3 text-emerald-400" /> SYNC: 99.8%</div>
            <div className="flex items-center gap-2"><Battery className="w-3 h-3 text-sky-400" /> ENERGY: MAX</div>
            <div className="flex items-center gap-2 text-emerald-500"><Wifi className="w-3 h-3" /> LINKED</div>
          </div>
          <button className="p-2.5 hover:bg-sky-500/10 rounded-full transition-all border border-transparent hover:border-sky-500/20 group">
            <Settings className="w-4 h-4 text-slate-400 group-hover:text-sky-400 transition-colors" />
          </button>
        </div>
      </header>

      {/* Main UI */}
      <main className="flex-1 flex overflow-hidden relative p-4 gap-4">
        <MemoryPanel memories={memories} />

        <div className="flex-1 flex flex-col items-center justify-center relative">
          {/* Floating UI Widget Left */}
          <div className="absolute left-10 top-10 border-l border-sky-500/30 pl-4 py-2 opacity-30">
             <div className="text-[10px] font-mono text-sky-400">MEM_DUMP_ACTIVE</div>
             <div className="text-[8px] text-slate-500">0x0021FFAD</div>
          </div>

          <HudCore status={status} />

          {/* Neural Link Control */}
          <div className="mt-12 flex flex-col items-center gap-6 group">
            <button
              onClick={handleStartLive}
              className={`relative flex items-center justify-center w-20 h-20 rounded-full transition-all duration-700 ${
                isLive ? 'bg-red-500 shadow-[0_0_30px_rgba(239,68,68,0.4)]' : 'bg-sky-500 shadow-[0_0_30px_rgba(14,165,233,0.4)]'
              }`}
            >
              <div className={`absolute inset-0 rounded-full border-2 border-white/20 ${isLive ? 'animate-ping' : ''}`} />
              <div className="absolute inset-2 border border-white/10 rounded-full" />
              {isLive ? <MicOff className="w-8 h-8" /> : <Mic className="w-8 h-8" />}
            </button>

            <div className="flex flex-col items-center">
               <span className="text-[10px] font-mono tracking-[0.5em] text-sky-500 uppercase opacity-50 mb-1">
                 {isLive ? 'Protocol Active' : 'Protocol Dormant'}
               </span>
               <div className="h-[2px] w-12 bg-sky-500/20" />
            </div>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </main>

      {/* Terminal View */}
      <Terminal logs={logs} />
    </div>
  );
};

export default App;

