  const [time, setTime] = useState(new Date());

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source, message, timestamp: Date.now(), type
    }].slice(-40));
  }, []);

  const handleStartLive = async () => {
    try {
      if (isLive) { stopLive(); return; }
      addLog('Initiating Neural Link...', 'SYSTEM', 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            setIsLive(true); setStatus(JarvisStatus.LISTENING);
            addLog('Neural Link Established.', 'JARVIS', 'success');

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              const video = videoRef.current;
              if (video && video.readyState >= 2) {
                const canvas = canvasRef.current; canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d'); ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(session => session.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.5);
              }
            }, 3000);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.inputTranscription) { addLog(m.serverContent.inputTranscription.text, 'OPERATOR'); setStatus(JarvisStatus.THINKING); }
            if (m.serverContent?.outputTranscription) { addLog(m.serverContent.outputTranscription.text, 'JARVIS'); setStatus(JarvisStatus.SPEAKING); }

            const audio = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audio) {
              const outCtx = audioContextRef.current?.output;
              if (outCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                const buf = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                const src = outCtx.createBufferSource(); src.buffer = buf; src.connect(outCtx.destination);
                src.onended = () => { sourcesRef.current.delete(src); if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); };
                src.start(nextStartTimeRef.current); nextStartTimeRef.current += buf.duration; sourcesRef.current.add(src);
              }
            }
            if (m.serverContent?.interrupted) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); nextStartTimeRef.current = 0; setStatus(JarvisStatus.LISTENING); }
          },
          onerror: () => { addLog('Neural link error.', 'SYSTEM', 'error'); stopLive(); },
          onclose: () => { addLog('Connection closed.', 'SYSTEM', 'info'); stopLive(); }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) { addLog('Initialization failed.', 'SYSTEM', 'error'); }
  };

  const stopLive = () => {
    setIsLive(false); setStatus(JarvisStatus.IDLE);
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (audioContextRef.current) { audioContextRef.current.input.close(); audioContextRef.current.output.close(); }
    if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-[#010409] text-slate-100 selection:bg-cyan-500/40 font-sans relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full pointer-events-none opacity-20">
         <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(34,211,238,0.05)_0%,transparent_70%)]" />
      </div>

      <header className="h-20 border-b border-cyan-500/10 bg-slate-900/20 backdrop-blur-3xl flex items-center justify-between px-10 z-20 relative">
        <div className="flex items-center gap-6">
          <div className="relative group">
            <Cpu className="w-8 h-8 text-cyan-400 group-hover:animate-pulse" />
            <div className="absolute -inset-2 bg-cyan-500/10 blur-md rounded-full" />
          </div>
          <div className="flex flex-col">
            <h1 className="text-2xl font-bold tracking-[0.4em] text-cyan-400 uppercase">JARVIS</h1>
            <span className="text-[10px] font-mono text-cyan-500/40 tracking-[0.2em] -mt-1">SECURE NEURAL OPERATING SYSTEM</span>
          </div>
        </div>

        <div className="flex items-center gap-12 font-mono text-[10px] tracking-widest text-slate-500">
          <div className="flex items-center gap-2 border-x border-white/5 px-6">
             <Clock className="w-3 h-3" /> {time.toLocaleTimeString()}
          </div>
          <div className="hidden lg:flex gap-8">
            <span className="flex items-center gap-2"><Layers className="w-3 h-3" /> BUFFER: 0%</span>
            <span className="flex items-center gap-2 text-cyan-400"><Shield className="w-3 h-3" /> LINK: {isLive ? 'ACTIVE' : 'READY'}</span>
            <span className="flex items-center gap-2 text-amber-400"><Zap className="w-3 h-3" /> POWER: MAX</span>
          </div>
          <button className="p-3 hover:bg-cyan-500/10 rounded-full transition-all border border-transparent hover:border-cyan-500/20 group">
            <Settings className="w-5 h-5 text-slate-500 group-hover:text-cyan-400" />
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        <MemoryPanel memories={memories} />

        <div className="flex-1 flex flex-col items-center justify-center relative">
          <HudCore status={status} />

          {/* Voice Visualization & Controls */}
          <div className="absolute bottom-10 flex flex-col items-center gap-8">
            <Waveform isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                      color={status === JarvisStatus.LISTENING ? '#4ade80' : '#22d3ee'} />

            <div className="flex flex-col items-center gap-4">
              <button
                onClick={handleStartLive}
                className={`relative w-24 h-24 rounded-full flex items-center justify-center transition-all duration-700 hover:scale-105 active:scale-95 ${
                  isLive ? 'bg-red-500 shadow-[0_0_50px_rgba(239,68,68,0.4)]' : 'bg-cyan-500 shadow-[0_0_50px_rgba(34,211,238,0.4)]'
                }`}
              >
                <div className={`absolute inset-0 rounded-full border-2 border-white/10 ${isLive ? 'animate-ping' : ''}`} />
                <div className="absolute inset-2 border border-white/5 rounded-full" />
                {isLive ? <MicOff className="w-10 h-10" /> : <Mic className="w-10 h-10" />}
              </button>
              <div className="text-[10px] font-mono tracking-[0.6em] text-cyan-500/50 uppercase">
                {isLive ? 'SYSTEM LINK ACTIVE' : 'INITIALIZE UPLINK'}
              </div>
            </div>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </main>

      <Terminal logs={logs} />
    </div>
  );
};

