                const canvas = canvasRef.current;
                canvas.width = 640; canvas.height = 480;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => s.sendRealtimeInput({
                        media: { data: base64Data, mimeType: 'image/jpeg' }
                      }));
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.6);
              }
            }, 4000);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.inputTranscription) { 
              addLog(m.serverContent.inputTranscription.text, 'OPERATOR'); 
              setStatus(JarvisStatus.THINKING); 
            }
            if (m.serverContent?.outputTranscription) { 
              addLog(m.serverContent.outputTranscription.text, 'JARVIS'); 
              setStatus(JarvisStatus.SPEAKING); 
            }

            const audio = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audio) {
              const outCtx = audioContextRef.current?.output;
              if (outCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                const buf = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                const src = outCtx.createBufferSource(); 
                src.buffer = buf; 
                src.connect(outCtx.destination);
                src.onended = () => { 
                  sourcesRef.current.delete(src); 
                  if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); 
                };
                src.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buf.duration;
                sourcesRef.current.add(src);
              }
            }
            if (m.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
            }
          },
          onerror: (e) => { addLog('Link Exception Detected.', 'SYSTEM', 'error'); stopLive(); },
          onclose: () => { addLog('Neural Link Severed.', 'SYSTEM', 'info'); stopLive(); }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) {
      addLog('Failed to initialize Neural Link.', 'SYSTEM', 'error');
    }
  };

  const stopLive = () => {
    setIsLive(false); setStatus(JarvisStatus.IDLE);
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (audioContextRef.current) { audioContextRef.current.input.close(); audioContextRef.current.output.close(); }
    if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    if (screenStreamRef.current) screenStreamRef.current.getTracks().forEach(t => t.stop());
    setIsScreenActive(false);
    isScreenActiveRef.current = false;
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden">

      {/* 1. TOP COMMAND BAR */}
      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-cyan-500/20 shadow-lg">
        <div className="flex items-center gap-12">
          <div className="flex flex-col">
            <div className="flex items-center gap-2 text-cyan-400 font-orbitron text-base tracking-[0.2em] text-glow">
              <Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}
            </div>
            <div className="text-[9px] font-mono text-slate-500 uppercase flex items-center gap-1.5 mt-0.5">
              <Calendar className="w-3 h-3" /> {time.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </div>
          </div>

          <div className="h-10 w-[1px] bg-white/10 hidden md:block" />

          <div className="hidden lg:flex items-center gap-3">
            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button 
                key={m}
                onClick={() => setMode(m)}
                className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${
                  mode === m 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow shadow-[0_0_15px_rgba(0,242,255,0.2)]' 
                    : 'border-white/5 text-slate-500 hover:border-white/20'
                }`}
              >
                {m}_MODE
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase">
              STATUS: {status}
            </span>
          </div>
          <button 
            onClick={stopLive}
            className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg"
          >
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY_STOP
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        {/* 2. LEFT SYSTEM PANEL */}
        <SystemMetrics />

        {/* 3. CENTER AI CORE PANEL */}
        <div className="flex-1 flex flex-col relative">
          <div className="flex-1 flex flex-col items-center justify-center relative">
            {/* Holographic HUD Core */}
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <HudCore status={status} />
            </div>

            {/* Terminal Console - Chat History */}
            <div className="z-10 w-full max-w-5xl h-[55%] glass rounded-xl overflow-hidden flex flex-col mt-auto shadow-2xl border-white/5 border-glow">
              <Terminal logs={logs} />
            </div>

            {/* Voice Waveform Overlay */}
            <div className="h-24 flex items-center justify-center mt-8 w-full z-20">
              <Waveform 
                isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : '#0041ff'} 
              />
            </div>
          </div>
        </div>

        {/* 4. RIGHT VISION PANEL */}
        <VisionPanel videoRef={videoRef} />
      </div>

      {/* 5. BOTTOM CONTROL PANEL */}
      <footer className="h-28 glass border-t border-cyan-500/20 flex items-center justify-center gap-16 z-50">
        <ControlButton icon={Mic} label="NEURAL_LINK" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={Monitor} label="OPTIC_VISION" active={true} color="blue" />
        <ControlButton icon={Layout} label="SCREEN_PERCEPTION" active={isScreenActive} onClick={handleToggleScreenPerception} color="purple" />
        <ControlButton icon={Database} label="MEMORY_CORE" color="cyan" />
        <ControlButton icon={Settings} label="SYSTEM_CONFIG" color="slate" />
        <ControlButton icon={TerminalIcon} label="CMD_OVERRIDE" color="cyan" />
      </footer>
    </div>
  );
};

