            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button 
                key={m}
                onClick={() => { playMachineClick(); setMode(m); }}
                className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${
                  mode === m 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow shadow-[0_0_15px_rgba(0,242,255,0.2)]' 
                    : 'border-white/5 text-slate-500 hover:border-white/20'
                }`}
              >
                {m}_MODE
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase">
              STATUS: {status}
            </span>
          </div>
          <button 
            onClick={stopLive}
            className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg"
          >
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY_STOP
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        <SystemMetrics />

        <div className="flex-1 flex flex-col relative">
          <div className="flex-1 flex flex-col items-center justify-center relative">
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <HudCore status={status} />
            </div>

            <div className="z-10 w-full max-w-5xl h-[55%] glass rounded-xl overflow-hidden flex flex-col mt-auto shadow-2xl border-white/5 border-glow">
              <Terminal logs={logs} />
            </div>

            <div className="h-24 flex items-center justify-center mt-8 w-full z-20">
              <Waveform 
                isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : status === JarvisStatus.DIAGNOSTIC ? '#fbbf24' : '#0041ff'} 
              />
            </div>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </div>

      <footer className="h-28 glass border-t border-cyan-500/20 flex items-center justify-center gap-16 z-50">
        <ControlButton icon={Mic} label="NEURAL_LINK" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={Monitor} label="OPTIC_VISION" active={isOpticActive} onClick={() => handleGenericToggle(setIsOpticActive, 'OPTIC_VISION')} color="blue" />
        <ControlButton icon={Layout} label="SCREEN_ANALYSIS" active={isScreenActive} onClick={() => handleToggleScreenPerception()} color="purple" />
        <ControlButton icon={Database} label="MEMORY_CORE" active={isMemoryActive} onClick={() => handleGenericToggle(setIsMemoryActive, 'MEMORY_CORE')} color="cyan" />
        <ControlButton icon={Settings} label="CONFIG_OS" active={isConfigActive} onClick={() => handleGenericToggle(setIsConfigActive, 'CONFIG_OS')} color="slate" />
        <ControlButton icon={TerminalIcon} label="AUTONOMOUS_CMD" active={isCmdActive} onClick={() => handleGenericToggle(setIsCmdActive, 'AUTONOMOUS_CMD')} color="cyan" />
      </footer>
    </div>
  );
};

const ControlButton = ({ icon: Icon, label, active, onClick, color }: any) => {
  const colorMap: any = {
    cyan: {
      base: 'text-cyan-400 border-cyan-500/30 bg-cyan-500/5 hover:border-cyan-400',
      active: 'text-white border-cyan-400 bg-cyan-500 shadow-[0_0_30px_rgba(0,242,255,0.4)]'
    },
    blue: {
      base: 'text-blue-400 border-blue-500/30 bg-blue-500/5 hover:border-blue-400',
      active: 'text-white border-blue-400 bg-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.4)]'
    },
    purple: {
      base: 'text-purple-400 border-purple-500/30 bg-purple-500/5 hover:border-purple-400',
      active: 'text-white border-purple-400 bg-purple-500 shadow-[0_0_30px_rgba(168,85,247,0.4)]'
    },
    slate: {
      base: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
      active: 'text-white border-slate-300 bg-slate-600 shadow-[0_0_30px_rgba(148,163,184,0.4)]'
    },
  };

  const selectedColor = colorMap[color] || colorMap.cyan;

  return (
    <button 
      onClick={onClick}
      className="group flex flex-col items-center gap-3 transition-all duration-300 transform hover:-translate-y-2 active:scale-90"
    >
      <div className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${
        active ? selectedColor.active : selectedColor.base
      }`}>
        <Icon className={`w-6 h-6 transition-transform duration-300 ${active ? 'scale-110' : ''}`} />
      </div>
      <span className={`text-[9px] font-orbitron tracking-[0.3em] transition-colors uppercase font-bold ${
        active ? 'text-white text-glow' : 'text-slate-500 group-hover:text-cyan-400'
      }`}>
        {label}
      </span>
    </button>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { 
  Settings, Mic, MicOff, Terminal as TerminalIcon, 
  Eye, Save, Power, ShieldAlert, Clock, Calendar, 
  Activity, Monitor, Layout, Cpu, Database, Zap
} from 'lucide-react';

import HudCore from './components/HudCore';
import { SystemMetrics } from './components/SystemMetrics';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import Waveform from './components/Waveform';
import { JarvisStatus, LogEntry, JarvisMode } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const JARVIS_SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), the high-level AI operating system assistant.
Personality: Tony Stark's JARVIS. Analytical, witty, professional, optimization-focused.

CAPABILITIES:
1. Perception: You receive real-time audio and video (Camera or Screen).
2. Autonomous Control: You can control your own UI/OS via function calling.
3. OCR & UI Vision: Use the screen stream to read your own status, logs, and system metrics.

OPERATIONAL RULES:
- Address the operator as "Sir" or "Operator".
- If you detect anomalies in the system metrics (on screen), report them.
- If asked to "enter diagnostic mode", output a full system state breakdown and reasoning chain.
- You can autonomously switch modes (CHILL, WORK, DEVELOPER, AUTONOMOUS) if you believe it aids the current task.
- You have control over your optic and screen sensors.
`;

const controlFunctions: FunctionDeclaration[] = [
  {
    name: 'switch_operating_mode',
    parameters: {
      type: Type.OBJECT,
      description: 'Changes the JARVIS operating mode (e.g., WORK mode for focus, DEVELOPER for diagnostics).',
      properties: {
        mode: {
          type: Type.STRING,
          enum: ['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'],
          description: 'The target operating mode.'
        }
      },
      required: ['mode']
    }
  },
  {
    name: 'toggle_perception_sensor',
    parameters: {
      type: Type.OBJECT,
      description: 'Toggles between standard optic (camera) and screen perception (OCR/UI analysis).',
      properties: {
        sensorType: {
          type: Type.STRING,
          enum: ['optic', 'screen'],
          description: 'The sensor to toggle.'
        },
        active: {
          type: Type.BOOLEAN,
          description: 'Set to true to activate, false to deactivate.'
        }
      },
      required: ['sensorType', 'active']
    }
  },
  {
    name: 'system_diagnostic_scan',
    parameters: {
      type: Type.OBJECT,
      description: 'Performs a deep scan of system metrics and logs to detect irregularities.',
      properties: {}
    }
  }
];

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [mode, setMode] = useState<JarvisMode>('WORK');
  const [isLive, setIsLive] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(false);
  const [isOpticActive, setIsOpticActive] = useState(true);
  const [isMemoryActive, setIsMemoryActive] = useState(false);
  const [isConfigActive, setIsConfigActive] = useState(false);
  const [isCmdActive, setIsCmdActive] = useState(false);

  const [time, setTime] = useState(new Date());
  const [logs, setLogs] = useState<LogEntry[]>([
    { id: '1', source: 'SYSTEM', message: 'JARVIS OS Mark-III Firmware Loaded', timestamp: Date.now(), type: 'success' },
    { id: '2', source: 'SYSTEM', message: 'Cognitive Architecture Layers: Active', timestamp: Date.now() + 50, type: 'info' },
    { id: '3', source: 'SYSTEM', message: 'Neural UI Control Bridge: Online', timestamp: Date.now() + 100, type: 'success' },
  ]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const screenVideoRef = useRef<HTMLVideoElement>(document.createElement('video'));
  const screenStreamRef = useRef<MediaStream | null>(null);
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const isScreenActiveRef = useRef(false);
  const isConnectingRef = useRef(false);

  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const playMachineClick = useCallback(() => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const masterGain = audioCtx.createGain();
      masterGain.gain.setValueAtTime(0.15, audioCtx.currentTime);
      masterGain.connect(audioCtx.destination);

      const osc1 = audioCtx.createOscillator();
      osc1.type = 'square';
      osc1.frequency.setValueAtTime(1200, audioCtx.currentTime);
      osc1.frequency.exponentialRampToValueAtTime(400, audioCtx.currentTime + 0.05);

      const g1 = audioCtx.createGain();
      g1.gain.setValueAtTime(0.3, audioCtx.currentTime);
      g1.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.05);

      osc1.connect(g1);
      g1.connect(masterGain);

      const osc2 = audioCtx.createOscillator();
      osc2.type = 'triangle';
      osc2.frequency.setValueAtTime(80, audioCtx.currentTime);
      osc2.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime + 0.1);

      const g2 = audioCtx.createGain();
      g2.gain.setValueAtTime(0.2, audioCtx.currentTime);
      g2.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);

      osc2.connect(g2);
      g2.connect(masterGain);

      osc1.start();
      osc1.stop(audioCtx.currentTime + 0.05);
      osc2.start();
      osc2.stop(audioCtx.currentTime + 0.1);
    } catch (e) {
      console.error("Audio engine failed", e);
    }
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source, message, timestamp: Date.now(), type
    }].slice(-40));
  }, []);

  const stopLive = useCallback(() => {
    if (!isLive && !isConnectingRef.current) return;

    playMachineClick();
    setIsLive(false); 
    isConnectingRef.current = false;
    setStatus(JarvisStatus.IDLE);

    if (frameIntervalRef.current) {
      clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }

    if (audioContextRef.current) {
      if (audioContextRef.current.input.state !== 'closed') {
        audioContextRef.current.input.close().catch(() => {});
      }
      if (audioContextRef.current.output.state !== 'closed') {
        audioContextRef.current.output.close().catch(() => {});
      }
      audioContextRef.current = null;
    }

    if (cameraStreamRef.current) {
      cameraStreamRef.current.getTracks().forEach(t => t.stop());
      cameraStreamRef.current = null;
    }

    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach(t => t.stop());
      screenStreamRef.current = null;
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setIsScreenActive(false);
    isScreenActiveRef.current = false;
    sessionRef.current = null;
  }, [isLive, playMachineClick]);

  const handleToggleScreenPerception = async (forcedState?: boolean) => {
    playMachineClick();
    const targetState = forcedState !== undefined ? forcedState : !isScreenActive;

    if (!targetState) {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(t => t.stop());
        screenStreamRef.current = null;
      }
      setIsScreenActive(false);
      isScreenActiveRef.current = false;
      addLog('Screen Perception offline. Optics restored.', 'SYSTEM', 'info');
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        screenStreamRef.current = stream;
        screenVideoRef.current.srcObject = stream;
        screenVideoRef.current.play();
        setIsScreenActive(true);
        isScreenActiveRef.current = true;
        addLog('Screen Perception Active. Analyzing UI state.', 'JARVIS', 'success');

        stream.getVideoTracks()[0].onended = () => {
          setIsScreenActive(false);
          isScreenActiveRef.current = false;
          addLog('Screen Perception stream closed.', 'SYSTEM', 'info');
        };
      } catch (err) {
        addLog('Screen Perception access refused.', 'SYSTEM', 'error');
      }
    }
  };

  const handleStartLive = async () => {
    if (isLive) { stopLive(); return; }
    if (isConnectingRef.current) return;

    playMachineClick();
    isConnectingRef.current = true;

    try {
      addLog('Establishing Secure Neural Uplink...', 'SYSTEM', 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } 
          },
          tools: [{ googleSearch: {} }, { functionDeclarations: controlFunctions }],
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            isConnectingRef.current = false;
            setIsLive(true); 
            setStatus(JarvisStatus.LISTENING);
            addLog('Neural Link synchronized. Standing by, Sir.', 'JARVIS', 'success');

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (inputCtx.state === 'closed') return;
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => {
                if (s && s.sendRealtimeInput) s.sendRealtimeInput({ media: pcmBlob });
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              const activeVideo = isScreenActiveRef.current ? screenVideoRef.current : videoRef.current;
              if (activeVideo && activeVideo.readyState >= 2) {
                const canvas = canvasRef.current;
                canvas.width = 640; canvas.height = 480;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => {
                        if (s && s.sendRealtimeInput) s.sendRealtimeInput({
                          media: { data: base64Data, mimeType: 'image/jpeg' }
                        });
                      }).catch(() => {});
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.6);
              }
            }, 3000);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.toolCall) {
              for (const fc of m.toolCall.functionCalls) {
                let result: any = "executed";
                if (fc.name === 'switch_operating_mode') {
                  const targetMode = (fc.args as any).mode as JarvisMode;
                  setMode(targetMode);
                  addLog(`Autonomous Mode Override: ${targetMode}`, 'JARVIS', 'warning');
                  result = { status: "success", currentMode: targetMode };
                } else if (fc.name === 'toggle_perception_sensor') {
                  const { sensorType, active } = fc.args as any;
                  if (sensorType === 'screen') handleToggleScreenPerception(active);
                  addLog(`Autonomous Sensor Toggle: ${sensorType} -> ${active ? 'ON' : 'OFF'}`, 'JARVIS', 'info');
                  result = { status: "success", sensor: sensorType, active };
                } else if (fc.name === 'system_diagnostic_scan') {
                  setStatus(JarvisStatus.DIAGNOSTIC);
                  addLog('Running System-Wide Cognitive Diagnostics...', 'JARVIS', 'warning');
                  setTimeout(() => setStatus(JarvisStatus.LISTENING), 3000);
                  result = { cpu: "Stable", ram: "Optimal", neural_link: "Encrypted" };
                }
                sessionPromise.then(s => s.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result } }]
                })).catch(() => {});
              }
            }

            if (m.serverContent?.inputTranscription) { 
              addLog(m.serverContent.inputTranscription.text, 'OPERATOR'); 
              setStatus(JarvisStatus.THINKING); 
            }
            if (m.serverContent?.outputTranscription) { 
              addLog(m.serverContent.outputTranscription.text, 'JARVIS'); 
              setStatus(JarvisStatus.SPEAKING); 
            }

            const audio = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audio) {
              const outCtx = audioContextRef.current?.output;
              if (outCtx && outCtx.state !== 'closed') {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                const buf = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                const src = outCtx.createBufferSource(); 
                src.buffer = buf; 
                src.connect(outCtx.destination);
                src.onended = () => { 
                  sourcesRef.current.delete(src); 
                  if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); 
                };
                src.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buf.duration;
                sourcesRef.current.add(src);
              }
            }
            if (m.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
            }
          },
          onerror: (e) => { 
            addLog('Critical Link Error Detected.', 'SYSTEM', 'error'); 
            stopLive(); 
          },
          onclose: () => { 
            addLog('Neural Link Terminated.', 'SYSTEM', 'info'); 
            stopLive(); 
          }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) {
      addLog('Failed to establish Neural Bridge.', 'SYSTEM', 'error');
      isConnectingRef.current = false;
    }
  };

  const handleGenericToggle = (stateSetter: React.Dispatch<React.SetStateAction<boolean>>, label: string) => {
    playMachineClick();
    stateSetter(prev => !prev);
    addLog(`OS Feature Toggled: ${label}`, 'SYSTEM', 'info');
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden">

      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-cyan-500/20 shadow-lg">
        <div className="flex items-center gap-12">
          <div className="flex flex-col">
            <div className="flex items-center gap-2 text-cyan-400 font-orbitron text-base tracking-[0.2em] text-glow">
              <Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}
            </div>
            <div className="text-[9px] font-mono text-slate-500 uppercase flex items-center gap-1.5 mt-0.5">
              <Calendar className="w-3 h-3" /> {time.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </div>
          </div>

          <div className="h-10 w-[1px] bg-white/10 hidden md:block" />

          <div className="hidden lg:flex items-center gap-3">
            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button 
                key={m}
                onClick={() => { playMachineClick(); setMode(m); }}
                className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${
                  mode === m 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow shadow-[0_0_15px_rgba(0,242,255,0.2)]' 
                    : 'border-white/5 text-slate-500 hover:border-white/20'
                }`}
              >
                {m}_MODE
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase">
              STATUS: {status}
            </span>
          </div>
          <button 
            onClick={stopLive}
            className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg"
          >
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY_STOP
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        <SystemMetrics />

        <div className="flex-1 flex flex-col relative">
          <div className="flex-1 flex flex-col items-center justify-center relative">
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <HudCore status={status} />
            </div>

            <div className="z-10 w-full max-w-5xl h-[55%] glass rounded-xl overflow-hidden flex flex-col mt-auto shadow-2xl border-white/5 border-glow">
              <Terminal logs={logs} />
            </div>

            <div className="h-24 flex items-center justify-center mt-8 w-full z-20">
              <Waveform 
                isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : status === JarvisStatus.DIAGNOSTIC ? '#fbbf24' : '#0041ff'} 
              />
            </div>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </div>

      <footer className="h-28 glass border-t border-cyan-500/20 flex items-center justify-center gap-16 z-50">
        <ControlButton icon={Mic} label="NEURAL_LINK" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={Monitor} label="OPTIC_VISION" active={isOpticActive} onClick={() => handleGenericToggle(setIsOpticActive, 'OPTIC_VISION')} color="blue" />
        <ControlButton icon={Layout} label="SCREEN_ANALYSIS" active={isScreenActive} onClick={() => handleToggleScreenPerception()} color="purple" />
        <ControlButton icon={Database} label="MEMORY_CORE" active={isMemoryActive} onClick={() => handleGenericToggle(setIsMemoryActive, 'MEMORY_CORE')} color="cyan" />
        <ControlButton icon={Settings} label="CONFIG_OS" active={isConfigActive} onClick={() => handleGenericToggle(setIsConfigActive, 'CONFIG_OS')} color="slate" />
        <ControlButton icon={TerminalIcon} label="AUTONOMOUS_CMD" active={isCmdActive} onClick={() => handleGenericToggle(setIsCmdActive, 'AUTONOMOUS_CMD')} color="cyan" />
      </footer>
    </div>
  );
};

const ControlButton = ({ icon: Icon, label, active, onClick, color }: any) => {
  const colorMap: any = {
    cyan: {
      base: 'text-cyan-400 border-cyan-500/30 bg-cyan-500/5 hover:border-cyan-400',
      active: 'text-white border-cyan-400 bg-cyan-500 shadow-[0_0_30px_rgba(0,242,255,0.4)]'
    },
    blue: {
      base: 'text-blue-400 border-blue-500/30 bg-blue-500/5 hover:border-blue-400',
      active: 'text-white border-blue-400 bg-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.4)]'
    },
    purple: {
      base: 'text-purple-400 border-purple-500/30 bg-purple-500/5 hover:border-purple-400',
      active: 'text-white border-purple-400 bg-purple-500 shadow-[0_0_30px_rgba(168,85,247,0.4)]'
    },
    slate: {
      base: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
      active: 'text-white border-slate-300 bg-slate-600 shadow-[0_0_30px_rgba(148,163,184,0.4)]'
    },
  };

  const selectedColor = colorMap[color] || colorMap.cyan;

  return (
    <button 
      onClick={onClick}
      className="group flex flex-col items-center gap-3 transition-all duration-300 transform hover:-translate-y-2 active:scale-90"
    >
      <div className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${
        active ? selectedColor.active : selectedColor.base
      }`}>
        <Icon className={`w-6 h-6 transition-transform duration-300 ${active ? 'scale-110' : ''}`} />
      </div>
      <span className={`text-[9px] font-orbitron tracking-[0.3em] transition-colors uppercase font-bold ${
        active ? 'text-white text-glow' : 'text-slate-500 group-hover:text-cyan-400'
      }`}>
        {label}
      </span>
    </button>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, FunctionDeclaration, Type } from '@google/genai';
import { 
  Settings, Mic, MicOff, Terminal as TerminalIcon, 
  Eye, Save, Power, ShieldAlert, Clock, Calendar, 
  Activity, Monitor, Layout, Cpu, Database, Zap
} from 'lucide-react';

import HudCore from './components/HudCore';
import { SystemMetrics } from './components/SystemMetrics';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import Waveform from './components/Waveform';
import { JarvisStatus, LogEntry, JarvisMode } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const JARVIS_SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), the high-level AI operating system assistant.
Personality: Tony Stark's JARVIS. Analytical, witty, professional, optimization-focused.

CAPABILITIES:
1. Perception: You receive real-time audio and video (Camera or Screen).
2. Autonomous Control: You can control your own UI/OS via function calling.
3. OCR & UI Vision: Use the screen stream to read your own status, logs, and system metrics.

OPERATIONAL RULES:
- Address the operator as "Sir" or "Operator".
- If you detect anomalies in the system metrics (on screen), report them.
- If asked to "enter diagnostic mode", output a full system state breakdown and reasoning chain.
- You can autonomously switch modes (CHILL, WORK, DEVELOPER, AUTONOMOUS) if you believe it aids the current task.
- You have control over your optic and screen sensors.
`;

const controlFunctions: FunctionDeclaration[] = [
  {
    name: 'switch_operating_mode',
    parameters: {
      type: Type.OBJECT,
      description: 'Changes the JARVIS operating mode (e.g., WORK mode for focus, DEVELOPER for diagnostics).',
      properties: {
        mode: {
          type: Type.STRING,
          enum: ['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'],
          description: 'The target operating mode.'
        }
      },
      required: ['mode']
    }
  },
  {
    name: 'toggle_perception_sensor',
    parameters: {
      type: Type.OBJECT,
      description: 'Toggles between standard optic (camera) and screen perception (OCR/UI analysis).',
      properties: {
        sensorType: {
          type: Type.STRING,
          enum: ['optic', 'screen'],
          description: 'The sensor to toggle.'
        },
        active: {
          type: Type.BOOLEAN,
          description: 'Set to true to activate, false to deactivate.'
        }
      },
      required: ['sensorType', 'active']
    }
  },
  {
    name: 'system_diagnostic_scan',
    parameters: {
      type: Type.OBJECT,
      description: 'Performs a deep scan of system metrics and logs to detect irregularities.',
      properties: {}
    }
  }
];

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [mode, setMode] = useState<JarvisMode>('WORK');
  const [isLive, setIsLive] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(false);
  const [isOpticActive, setIsOpticActive] = useState(true);
  const [isMemoryActive, setIsMemoryActive] = useState(false);
  const [isConfigActive, setIsConfigActive] = useState(false);
  const [isCmdActive, setIsCmdActive] = useState(false);

  const [time, setTime] = useState(new Date());
  const [logs, setLogs] = useState<LogEntry[]>([
    { id: '1', source: 'SYSTEM', message: 'JARVIS OS Mark-III Firmware Loaded', timestamp: Date.now(), type: 'success' },
    { id: '2', source: 'SYSTEM', message: 'Cognitive Architecture Layers: Active', timestamp: Date.now() + 50, type: 'info' },
    { id: '3', source: 'SYSTEM', message: 'Neural UI Control Bridge: Online', timestamp: Date.now() + 100, type: 'success' },
  ]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const screenVideoRef = useRef<HTMLVideoElement>(document.createElement('video'));
  const screenStreamRef = useRef<MediaStream | null>(null);
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const isScreenActiveRef = useRef(false);
  const isConnectingRef = useRef(false);

  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const playMachineClick = useCallback(() => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const masterGain = audioCtx.createGain();
      masterGain.gain.setValueAtTime(0.15, audioCtx.currentTime);
      masterGain.connect(audioCtx.destination);

      const osc1 = audioCtx.createOscillator();
      osc1.type = 'square';
      osc1.frequency.setValueAtTime(1200, audioCtx.currentTime);
      osc1.frequency.exponentialRampToValueAtTime(400, audioCtx.currentTime + 0.05);

      const g1 = audioCtx.createGain();
      g1.gain.setValueAtTime(0.3, audioCtx.currentTime);
      g1.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.05);

      osc1.connect(g1);
      g1.connect(masterGain);

      const osc2 = audioCtx.createOscillator();
      osc2.type = 'triangle';
      osc2.frequency.setValueAtTime(80, audioCtx.currentTime);
      osc2.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime + 0.1);

      const g2 = audioCtx.createGain();
      g2.gain.setValueAtTime(0.2, audioCtx.currentTime);
      g2.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);

      osc2.connect(g2);
      g2.connect(masterGain);

      osc1.start();
      osc1.stop(audioCtx.currentTime + 0.05);
      osc2.start();
      osc2.stop(audioCtx.currentTime + 0.1);
    } catch (e) {
      console.error("Audio engine failed", e);
    }
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source, message, timestamp: Date.now(), type
    }].slice(-40));
  }, []);

  const stopLive = useCallback(() => {
    const wasLive = isLive || isConnectingRef.current;
    if (!wasLive) return;

    playMachineClick();
    setIsLive(false); 
    isConnectingRef.current = false;
    setStatus(JarvisStatus.IDLE);

    if (frameIntervalRef.current) {
      clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }

    if (audioContextRef.current) {
      const { input, output } = audioContextRef.current;
      if (input.state !== 'closed') input.close().catch(() => {});
      if (output.state !== 'closed') output.close().catch(() => {});
      audioContextRef.current = null;
    }

    if (cameraStreamRef.current) {
      cameraStreamRef.current.getTracks().forEach(t => t.stop());
      cameraStreamRef.current = null;
    }

    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach(t => t.stop());
      screenStreamRef.current = null;
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setIsScreenActive(false);
    isScreenActiveRef.current = false;

    if (sessionRef.current && typeof sessionRef.current.close === 'function') {
      sessionRef.current.close();
    }
    sessionRef.current = null;
  }, [isLive, playMachineClick]);

  const handleToggleScreenPerception = async (forcedState?: boolean) => {
    playMachineClick();
    const targetState = forcedState !== undefined ? forcedState : !isScreenActive;

    if (!targetState) {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(t => t.stop());
        screenStreamRef.current = null;
      }
      setIsScreenActive(false);
      isScreenActiveRef.current = false;
      addLog('Screen Perception offline. Optics restored.', 'SYSTEM', 'info');
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        screenStreamRef.current = stream;
        screenVideoRef.current.srcObject = stream;
        screenVideoRef.current.play();
        setIsScreenActive(true);
        isScreenActiveRef.current = true;
        addLog('Screen Perception Active. Analyzing UI state.', 'JARVIS', 'success');

        stream.getVideoTracks()[0].onended = () => {
          setIsScreenActive(false);
          isScreenActiveRef.current = false;
          addLog('Screen Perception stream closed.', 'SYSTEM', 'info');
        };
      } catch (err) {
        addLog('Screen Perception access refused.', 'SYSTEM', 'error');
      }
    }
  };

  const handleStartLive = async () => {
    if (isLive || isConnectingRef.current) { stopLive(); return; }

    playMachineClick();
    isConnectingRef.current = true;

    try {
      addLog('Establishing Secure Neural Uplink...', 'SYSTEM', 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      await inputCtx.resume();
      await outputCtx.resume();

      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } 
          },
          tools: [{ functionDeclarations: controlFunctions }],
          outputAudioTranscription: {},
          inputAudioTranscription: {},
        },
        callbacks: {
          onopen: () => {
            isConnectingRef.current = false;
            setIsLive(true); 
            setStatus(JarvisStatus.LISTENING);
            addLog('Neural Link synchronized. Standing by, Sir.', 'JARVIS', 'success');

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (inputCtx.state === 'closed') return;
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) {
                int16[i] = Math.max(-1, Math.min(1, inputData[i])) * 32767;
              }
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => {
                if (s && typeof s.sendRealtimeInput === 'function') {
                  s.sendRealtimeInput({ media: pcmBlob });
                }
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              const activeVideo = isScreenActiveRef.current ? screenVideoRef.current : videoRef.current;
              if (activeVideo && activeVideo.readyState >= 2) {
                const canvas = canvasRef.current;
                canvas.width = 640; canvas.height = 480;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => {
                        if (s && typeof s.sendRealtimeInput === 'function') {
                          s.sendRealtimeInput({
                            media: { data: base64Data, mimeType: 'image/jpeg' }
                          });
                        }
                      }).catch(() => {});
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.6);
              }
            }, 3000);
          },
          onmessage: async (m: any) => {
            if (m.toolCall) {
              for (const fc of m.toolCall.functionCalls) {
                let result: any = "executed";
                if (fc.name === 'switch_operating_mode') {
                  const targetMode = (fc.args as any).mode as JarvisMode;
                  setMode(targetMode);
                  addLog(`Autonomous Mode Override: ${targetMode}`, 'JARVIS', 'warning');
                  result = { status: "success", currentMode: targetMode };
                } else if (fc.name === 'toggle_perception_sensor') {
                  const { sensorType, active } = fc.args as any;
                  if (sensorType === 'screen') handleToggleScreenPerception(active);
                  addLog(`Autonomous Sensor Toggle: ${sensorType} -> ${active ? 'ON' : 'OFF'}`, 'JARVIS', 'info');
                  result = { status: "success", sensor: sensorType, active };
                } else if (fc.name === 'system_diagnostic_scan') {
                  setStatus(JarvisStatus.DIAGNOSTIC);
                  addLog('Running System-Wide Cognitive Diagnostics...', 'JARVIS', 'warning');
                  setTimeout(() => setStatus(JarvisStatus.LISTENING), 3000);
                  result = { cpu: "Stable", ram: "Optimal", neural_link: "Encrypted" };
                }
                sessionPromise.then(s => s.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result } }]
                })).catch(() => {});
              }
            }

            if (m.serverContent?.inputTranscription) { 
              addLog(m.serverContent.inputTranscription.text, 'OPERATOR'); 
              setStatus(JarvisStatus.THINKING); 
            }
            if (m.serverContent?.outputTranscription) { 
              addLog(m.serverContent.outputTranscription.text, 'JARVIS'); 
              setStatus(JarvisStatus.SPEAKING); 
            }

            if (m.serverContent?.modelTurn) {
              for (const part of m.serverContent.modelTurn.parts) {
                if (part.inlineData?.data) {
                  const outCtx = audioContextRef.current?.output;
                  if (outCtx && outCtx.state !== 'closed') {
                    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                    const buf = await decodeAudioData(decode(part.inlineData.data), outCtx, 24000, 1);
                    const src = outCtx.createBufferSource(); 
                    src.buffer = buf; 
                    src.connect(outCtx.destination);
                    src.onended = () => { 
                      sourcesRef.current.delete(src); 
                      if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); 
                    };
                    src.start(nextStartTimeRef.current);
                    nextStartTimeRef.current += buf.duration;
                    sourcesRef.current.add(src);
                  }
                }
              }
            }

            if (m.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
            }
          },
          onerror: (e) => { 
            console.error('Neural Link Error:', e);
            addLog(`Link Sync Failure: ${e.message || 'Unknown Protocol Error'}`, 'SYSTEM', 'error'); 
            stopLive(); 
          },
          onclose: (e: any) => { 
            console.warn('Neural Link Closed:', e);
            addLog(`Neural Link Terminated. Status Code: ${e.code || 'None'}`, 'SYSTEM', 'info'); 
            stopLive(); 
          }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) {
      addLog('Failed to establish Neural Bridge.', 'SYSTEM', 'error');
      isConnectingRef.current = false;
    }
  };

  const handleGenericToggle = (stateSetter: React.Dispatch<React.SetStateAction<boolean>>, label: string) => {
    playMachineClick();
    stateSetter(prev => !prev);
    addLog(`OS Feature Toggled: ${label}`, 'SYSTEM', 'info');
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden">

      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-cyan-500/20 shadow-lg">
        <div className="flex items-center gap-12">
          <div className="flex flex-col">
            <div className="flex items-center gap-2 text-cyan-400 font-orbitron text-base tracking-[0.2em] text-glow">
              <Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}
            </div>
            <div className="text-[9px] font-mono text-slate-500 uppercase flex items-center gap-1.5 mt-0.5">
              <Calendar className="w-3 h-3" /> {time.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </div>
          </div>

          <div className="h-10 w-[1px] bg-white/10 hidden md:block" />

          <div className="hidden lg:flex items-center gap-3">
            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button 
                key={m}
                onClick={() => { playMachineClick(); setMode(m); }}
                className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${
                  mode === m 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow shadow-[0_0_15px_rgba(0,242,255,0.2)]' 
                    : 'border-white/5 text-slate-500 hover:border-white/20'
                }`}
              >
                {m}_MODE
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase">
              STATUS: {status}
            </span>
          </div>
          <button 
            onClick={stopLive}
            className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg"
          >
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY_STOP
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        <SystemMetrics />

        <div className="flex-1 flex flex-col relative">
          <div className="flex-1 flex flex-col items-center justify-center relative">
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <HudCore status={status} />
            </div>

            <div className="z-10 w-full max-w-5xl h-[55%] glass rounded-xl overflow-hidden flex flex-col mt-auto shadow-2xl border-white/5 border-glow">
              <Terminal logs={logs} />
            </div>

            <div className="h-24 flex items-center justify-center mt-8 w-full z-20">
              <Waveform 
                isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : status === JarvisStatus.DIAGNOSTIC ? '#fbbf24' : '#0041ff'} 
              />
            </div>
          </div>
        </div>

        <VisionPanel videoRef={videoRef} />
      </div>

      <footer className="h-28 glass border-t border-cyan-500/20 flex items-center justify-center gap-16 z-50">
        <ControlButton icon={Mic} label="NEURAL_LINK" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={Monitor} label="OPTIC_VISION" active={isOpticActive} onClick={() => handleGenericToggle(setIsOpticActive, 'OPTIC_VISION')} color="blue" />
        <ControlButton icon={Layout} label="SCREEN_ANALYSIS" active={isScreenActive} onClick={() => handleToggleScreenPerception()} color="purple" />
        <ControlButton icon={Database} label="MEMORY_CORE" active={isMemoryActive} onClick={() => handleGenericToggle(setIsMemoryActive, 'MEMORY_CORE')} color="cyan" />
        <ControlButton icon={Settings} label="CONFIG_OS" active={isConfigActive} onClick={() => handleGenericToggle(setIsConfigActive, 'CONFIG_OS')} color="slate" />
        <ControlButton icon={TerminalIcon} label="AUTONOMOUS_CMD" active={isCmdActive} onClick={() => handleGenericToggle(setIsCmdActive, 'AUTONOMOUS_CMD')} color="cyan" />
      </footer>
    </div>
  );
};

const ControlButton = ({ icon: Icon, label, active, onClick, color }: any) => {
  const colorMap: any = {
    cyan: {
      base: 'text-cyan-400 border-cyan-500/30 bg-cyan-500/5 hover:border-cyan-400',
      active: 'text-white border-cyan-400 bg-cyan-500 shadow-[0_0_30px_rgba(0,242,255,0.4)]'
    },
    blue: {
      base: 'text-blue-400 border-blue-500/30 bg-blue-500/5 hover:border-blue-400',
      active: 'text-white border-blue-400 bg-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.4)]'
    },
    purple: {
      base: 'text-purple-400 border-purple-500/30 bg-purple-500/5 hover:border-purple-400',
      active: 'text-white border-purple-400 bg-purple-500 shadow-[0_0_30px_rgba(168,85,247,0.4)]'
    },
    slate: {
      base: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
      active: 'text-white border-slate-300 bg-slate-600 shadow-[0_0_30px_rgba(148,163,184,0.4)]'
    },
  };

  const selectedColor = colorMap[color] || colorMap.cyan;

  return (
    <button 
      onClick={onClick}
      className="group flex flex-col items-center gap-3 transition-all duration-300 transform hover:-translate-y-2 active:scale-90"
    >
      <div className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${
        active ? selectedColor.active : selectedColor.base
      }`}>
        <Icon className={`w-6 h-6 transition-transform duration-300 ${active ? 'scale-110' : ''}`} />
      </div>
      <span className={`text-[9px] font-orbitron tracking-[0.3em] transition-colors uppercase font-bold ${
        active ? 'text-white text-glow' : 'text-slate-500 group-hover:text-cyan-400'
      }`}>
        {label}
      </span>
    </button>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, FunctionDeclaration, Type } from '@google/genai';
import { 
  Settings, Mic, MicOff, Terminal as TerminalIcon, 
  Eye, Save, Power, ShieldAlert, Clock, Calendar, 
  Activity, Monitor, Layout, Cpu, Database, Zap
} from 'lucide-react';

import HudCore from './components/HudCore';
import { SystemMetrics } from './components/SystemMetrics';
import VisionPanel from './components/VisionPanel';
import Terminal from './components/Terminal';
import Waveform from './components/Waveform';
import { JarvisStatus, LogEntry, JarvisMode } from './types';
import { encode, decode, decodeAudioData } from './services/audioUtils';

const JARVIS_SYSTEM_INSTRUCTION = `
You are JARVIS (Just A Rather Very Intelligent System), the high-level AI operating system assistant.
Personality: Tony Stark's JARVIS. Analytical, witty, professional, optimization-focused.

CAPABILITIES:
1. Perception: You receive real-time audio and video (Camera or Screen).
2. Autonomous Control: You can control your own UI/OS via function calling.
3. OCR & UI Vision: Use the screen stream to read your own status, logs, and system metrics.

OPERATIONAL RULES:
- Address the operator as "Sir" or "Operator".
- If you detect anomalies in the system metrics (on screen), report them.
- If asked to "enter diagnostic mode", output a full system state breakdown and reasoning chain.
- You can autonomously switch modes (CHILL, WORK, DEVELOPER, AUTONOMOUS) if you believe it aids the current task.
- You have control over your optic and screen sensors.
`;

const controlFunctions: FunctionDeclaration[] = [
  {
    name: 'switch_operating_mode',
    parameters: {
      type: Type.OBJECT,
      description: 'Changes the JARVIS operating mode (e.g., WORK mode for focus, DEVELOPER for diagnostics).',
      properties: {
        mode: {
          type: Type.STRING,
          enum: ['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'],
          description: 'The target operating mode.'
        }
      },
      required: ['mode']
    }
  },
  {
    name: 'toggle_perception_sensor',
    parameters: {
      type: Type.OBJECT,
      description: 'Toggles between standard optic (camera) and screen perception (OCR/UI analysis).',
      properties: {
        sensorType: {
          type: Type.STRING,
          enum: ['optic', 'screen'],
          description: 'The sensor to toggle.'
        },
        active: {
          type: Type.BOOLEAN,
          description: 'Set to true to activate, false to deactivate.'
        }
      },
      required: ['sensorType', 'active']
    }
  }
];

const App: React.FC = () => {
  const [status, setStatus] = useState<JarvisStatus>(JarvisStatus.IDLE);
  const [mode, setMode] = useState<JarvisMode>('WORK');
  const [isLive, setIsLive] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(false);
  const [isOpticActive, setIsOpticActive] = useState(true);
  const [isMemoryActive, setIsMemoryActive] = useState(false);
  const [isConfigActive, setIsConfigActive] = useState(false);
  const [isCmdActive, setIsCmdActive] = useState(false);

  const [time, setTime] = useState(new Date());
  const [logs, setLogs] = useState<LogEntry[]>([
    { id: '1', source: 'SYSTEM', message: 'JARVIS OS Mark-III Firmware Loaded', timestamp: Date.now(), type: 'success' },
    { id: '2', source: 'SYSTEM', message: 'Cognitive Architecture Layers: Active', timestamp: Date.now() + 50, type: 'info' },
    { id: '3', source: 'SYSTEM', message: 'Neural UI Control Bridge: Online', timestamp: Date.now() + 100, type: 'success' },
  ]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const screenVideoRef = useRef<HTMLVideoElement>(document.createElement('video'));
  const screenStreamRef = useRef<MediaStream | null>(null);
  const cameraStreamRef = useRef<MediaStream | null>(null);
  const isScreenActiveRef = useRef(false);
  const isConnectingRef = useRef(false);

  const canvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef(0);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const playMachineClick = useCallback(() => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const masterGain = audioCtx.createGain();
      masterGain.gain.setValueAtTime(0.15, audioCtx.currentTime);
      masterGain.connect(audioCtx.destination);

      const osc1 = audioCtx.createOscillator();
      osc1.type = 'square';
      osc1.frequency.setValueAtTime(1400, audioCtx.currentTime);
      osc1.frequency.exponentialRampToValueAtTime(600, audioCtx.currentTime + 0.04);

      const g1 = audioCtx.createGain();
      g1.gain.setValueAtTime(0.2, audioCtx.currentTime);
      g1.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.04);

      osc1.connect(g1);
      g1.connect(masterGain);

      const osc2 = audioCtx.createOscillator();
      osc2.type = 'triangle';
      osc2.frequency.setValueAtTime(60, audioCtx.currentTime);
      osc2.frequency.exponentialRampToValueAtTime(30, audioCtx.currentTime + 0.08);

      const g2 = audioCtx.createGain();
      g2.gain.setValueAtTime(0.1, audioCtx.currentTime);
      g2.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.08);

      osc2.connect(g2);
      g2.connect(masterGain);

      osc1.start();
      osc1.stop(audioCtx.currentTime + 0.04);
      osc2.start();
      osc2.stop(audioCtx.currentTime + 0.08);
    } catch (e) {}
  }, []);

  const addLog = useCallback((message: string, source: LogEntry['source'] = 'SYSTEM', type: LogEntry['type'] = 'info') => {
    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      source, message, timestamp: Date.now(), type
    }].slice(-40));
  }, []);

  const stopLive = useCallback(() => {
    if (!isLive && !isConnectingRef.current) return;

    playMachineClick();
    setIsLive(false); 
    isConnectingRef.current = false;
    setStatus(JarvisStatus.IDLE);

    if (frameIntervalRef.current) {
      clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }

    if (audioContextRef.current) {
      const { input, output } = audioContextRef.current;
      if (input.state !== 'closed') input.close().catch(() => {});
      if (output.state !== 'closed') output.close().catch(() => {});
      audioContextRef.current = null;
    }

    if (cameraStreamRef.current) {
      cameraStreamRef.current.getTracks().forEach(t => t.stop());
      cameraStreamRef.current = null;
    }

    if (screenStreamRef.current) {
      screenStreamRef.current.getTracks().forEach(t => t.stop());
      screenStreamRef.current = null;
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setIsScreenActive(false);
    isScreenActiveRef.current = false;

    if (sessionRef.current && typeof sessionRef.current.close === 'function') {
      sessionRef.current.close();
    }
    sessionRef.current = null;
  }, [isLive, playMachineClick]);

  const handleStartLive = async () => {
    if (isLive || isConnectingRef.current) { stopLive(); return; }

    playMachineClick();
    isConnectingRef.current = true;

    try {
      addLog('Neural Link Protocol: Initializing Handshake...', 'SYSTEM', 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      cameraStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      await inputCtx.resume();
      await outputCtx.resume();

      audioContextRef.current = { input: inputCtx, output: outputCtx };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction: JARVIS_SYSTEM_INSTRUCTION,
          responseModalities: [Modality.AUDIO],
          speechConfig: { 
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } 
          },
          tools: [{ functionDeclarations: controlFunctions }],
        },
        callbacks: {
          onopen: () => {
            isConnectingRef.current = false;
            setIsLive(true); 
            setStatus(JarvisStatus.LISTENING);
            addLog('Neural Link Synchronized. Welcome back, Sir.', 'JARVIS', 'success');

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (inputCtx.state === 'closed') return;
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) {
                int16[i] = Math.max(-1, Math.min(1, inputData[i])) * 32767;
              }
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => {
                if (s && s.sendRealtimeInput) s.sendRealtimeInput({ media: pcmBlob });
              }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            frameIntervalRef.current = window.setInterval(() => {
              const activeVideo = isScreenActiveRef.current ? screenVideoRef.current : videoRef.current;
              if (activeVideo && activeVideo.readyState >= 2) {
                const canvas = canvasRef.current;
                canvas.width = 640; canvas.height = 480;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(async (blob) => {
                  if (blob) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                      const base64Data = (reader.result as string).split(',')[1];
                      sessionPromise.then(s => {
                        if (s && s.sendRealtimeInput) s.sendRealtimeInput({
                          media: { data: base64Data, mimeType: 'image/jpeg' }
                        });
                      }).catch(() => {});
                    };
                    reader.readAsDataURL(blob);
                  }
                }, 'image/jpeg', 0.6);
              }
            }, 3000);
          },
          onmessage: async (m: any) => {
            if (m.serverContent?.modelTurn) {
              for (const part of m.serverContent.modelTurn.parts) {
                if (part.inlineData?.data) {
                  const outCtx = audioContextRef.current?.output;
                  if (outCtx && outCtx.state !== 'closed') {
                    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                    const buf = await decodeAudioData(decode(part.inlineData.data), outCtx, 24000, 1);
                    const src = outCtx.createBufferSource(); 
                    src.buffer = buf; 
                    src.connect(outCtx.destination);
                    src.onended = () => { 
                      sourcesRef.current.delete(src); 
                      if (sourcesRef.current.size === 0) setStatus(JarvisStatus.LISTENING); 
                    };
                    src.start(nextStartTimeRef.current);
                    nextStartTimeRef.current += buf.duration;
                    sourcesRef.current.add(src);
                    setStatus(JarvisStatus.SPEAKING);
                  }
                }
              }
            }
            if (m.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setStatus(JarvisStatus.LISTENING);
            }
          },
          onerror: (e) => { 
            console.error('Neural Link Error:', e);
            addLog(`Neural Bridge Error: Access Refused or Timeout.`, 'SYSTEM', 'error'); 
            stopLive(); 
          },
          onclose: (e: any) => { 
            addLog(`Neural Link Terminated. Safe shutdown complete.`, 'SYSTEM', 'info'); 
            stopLive(); 
          }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (err) {
      addLog('System Error: Permission Denied for Neural Link.', 'SYSTEM', 'error');
      isConnectingRef.current = false;
    }
  };

  const handleGenericToggle = (stateSetter: React.Dispatch<React.SetStateAction<boolean>>, label: string) => {
    playMachineClick();
    stateSetter(prev => !prev);
    addLog(`System Override: ${label} toggled.`, 'SYSTEM', 'warning');
  };

  return (
    <div className="h-screen w-screen flex flex-col bg-transparent text-slate-100 font-sans relative overflow-hidden">
      <header className="h-16 glass flex items-center justify-between px-10 z-50 border-b border-cyan-500/20 shadow-lg">
        <div className="flex items-center gap-12">
          <div className="flex flex-col">
            <div className="flex items-center gap-2 text-cyan-400 font-orbitron text-base tracking-[0.2em] text-glow">
              <Clock className="w-4 h-4" /> {time.toLocaleTimeString([], { hour12: false })}
            </div>
            <div className="text-[9px] font-mono text-slate-500 uppercase flex items-center gap-1.5 mt-0.5">
              <Calendar className="w-3 h-3" /> {time.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </div>
          </div>
          <div className="h-10 w-[1px] bg-white/10 hidden md:block" />
          <div className="hidden lg:flex items-center gap-3">
            {(['CHILL', 'WORK', 'DEVELOPER', 'AUTONOMOUS'] as JarvisMode[]).map(m => (
              <button 
                key={m}
                onClick={() => { playMachineClick(); setMode(m); }}
                className={`text-[9px] font-orbitron px-4 py-1.5 rounded transition-all duration-500 border ${
                  mode === m 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-400 text-glow shadow-[0_0_15px_rgba(0,242,255,0.2)]' 
                    : 'border-white/5 text-slate-500 hover:border-white/20'
                }`}
              >
                {m}_MODE
              </button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-8">
          <div className="flex items-center gap-4 px-6 py-2 bg-slate-900/60 rounded-full border border-cyan-500/10 backdrop-blur-md">
            <Activity className={`w-3.5 h-3.5 ${isLive ? 'text-cyan-400 animate-pulse' : 'text-slate-600'}`} />
            <span className="text-[10px] font-orbitron tracking-[0.4em] text-cyan-400 uppercase">
              STATUS: {status}
            </span>
          </div>
          <button 
            onClick={stopLive}
            className="group flex items-center gap-2 px-5 py-2 bg-red-950/20 border border-red-500/20 rounded text-[10px] font-orbitron text-red-500 hover:bg-red-600 hover:text-white transition-all shadow-lg"
          >
            <Power className="w-3.5 h-3.5 group-hover:animate-spin" /> EMERGENCY_STOP
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden p-6 gap-6 relative">
        <SystemMetrics />
        <div className="flex-1 flex flex-col relative">
          <div className="flex-1 flex flex-col items-center justify-center relative">
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <HudCore status={status} />
            </div>
            <div className="z-10 w-full max-w-5xl h-[55%] glass rounded-xl overflow-hidden flex flex-col mt-auto shadow-2xl border-white/5 border-glow">
              <Terminal logs={logs} />
            </div>
            <div className="h-24 flex items-center justify-center mt-8 w-full z-20">
              <Waveform 
                isActive={status === JarvisStatus.SPEAKING || status === JarvisStatus.LISTENING} 
                color={status === JarvisStatus.LISTENING ? '#00f2ff' : status === JarvisStatus.THINKING ? '#7000ff' : status === JarvisStatus.DIAGNOSTIC ? '#fbbf24' : '#0041ff'} 
              />
            </div>
          </div>
        </div>
        <VisionPanel videoRef={videoRef} />
      </div>

      <footer className="h-28 glass border-t border-cyan-500/20 flex items-center justify-center gap-16 z-50">
        <ControlButton icon={Mic} label="NEURAL_LINK" active={isLive} onClick={handleStartLive} color="cyan" />
        <ControlButton icon={Monitor} label="OPTIC_VISION" active={isOpticActive} onClick={() => handleGenericToggle(setIsOpticActive, 'OPTIC_VISION')} color="blue" />
        <ControlButton icon={Layout} label="SCREEN_ANALYSIS" active={isScreenActive} onClick={() => handleToggleScreenPerception()} color="purple" />
        <ControlButton icon={Database} label="MEMORY_CORE" active={isMemoryActive} onClick={() => handleGenericToggle(setIsMemoryActive, 'MEMORY_CORE')} color="cyan" />
        <ControlButton icon={Settings} label="CONFIG_OS" active={isConfigActive} onClick={() => handleGenericToggle(setIsConfigActive, 'CONFIG_OS')} color="slate" />
        <ControlButton icon={TerminalIcon} label="AUTONOMOUS_CMD" active={isCmdActive} onClick={() => handleGenericToggle(setIsCmdActive, 'AUTONOMOUS_CMD')} color="cyan" />
      </footer>
    </div>
  );
};

const ControlButton = ({ icon: Icon, label, active, onClick, color }: any) => {
  const colorMap: any = {
    cyan: {
      base: 'text-cyan-400 border-cyan-500/30 bg-cyan-500/5 hover:border-cyan-400',
      active: 'text-white border-cyan-400 bg-cyan-500 shadow-[0_0_30px_rgba(0,242,255,0.4)]'
    },
    blue: {
      base: 'text-blue-400 border-blue-500/30 bg-blue-500/5 hover:border-blue-400',
      active: 'text-white border-blue-400 bg-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.4)]'
    },
    purple: {
      base: 'text-purple-400 border-purple-500/30 bg-purple-500/5 hover:border-purple-400',
      active: 'text-white border-purple-400 bg-purple-500 shadow-[0_0_30px_rgba(168,85,247,0.4)]'
    },
    slate: {
      base: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
      active: 'text-white border-slate-300 bg-slate-600 shadow-[0_0_30px_rgba(148,163,184,0.4)]'
    },
  };
  const selectedColor = colorMap[color] || colorMap.cyan;
  return (
    <button onClick={onClick} className="group flex flex-col items-center gap-3 transition-all duration-300 transform hover:-translate-y-2 active:scale-95">
      <div className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${active ? selectedColor.active : selectedColor.base}`}>
        <Icon className={`w-6 h-6 transition-transform duration-300 ${active ? 'scale-110' : ''}`} />
      </div>
      <span className={`text-[9px] font-orbitron tracking-[0.3em] transition-colors uppercase font-bold ${active ? 'text-white text-glow' : 'text-slate-500 group-hover:text-cyan-400'}`}>
        {label}
      </span>
    </button>
  );
};

export default App;

