  // Simulated initial sessions for visualization
  const [sessions, setSessions] = useState<ChatSession[]>([
    {
      session_id: 's1',
      title: 'Neural Core Optimization',
      timestamp_created: Date.now() - 3600000,
      timestamp_last_message: Date.now() - 600000,
      last_message_preview: "Sir, I have recalibrated the thermal sensors in Sector 4.",
      mode: 'DEVELOPER',
      model: 'gemini-2.5-flash',
      isPinned: true,
      messageCount: 42,
      memorySaved: true
    },
    {
      session_id: 's2',
      title: 'Project Mark-III Schematics',
      timestamp_created: Date.now() - 86400000,
      timestamp_last_message: Date.now() - 86400000 + 3600000,
      last_message_preview: "Analyzing the 3D model for the new HUD overlay...",
      mode: 'WORK',
      model: 'gemini-2.5-pro',
      messageCount: 15,
      memorySaved: true
    },
    {
      session_id: 's3',
      title: 'Hinglish Logic Test',
      timestamp_created: Date.now() - 2 * 86400000,
      timestamp_last_message: Date.now() - 2 * 86400000 + 7200000,
      last_message_preview: "The dual-language logic is processing optimally.",
      mode: 'CHILL',
      model: 'gemini-2.5-flash',
      messageCount: 8,
      memorySaved: false
    }
  ]);

  const filteredSessions = useMemo(() => {
    return sessions.filter(s => 
      s.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.last_message_preview.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [sessions, searchQuery]);

  const groupSessions = (sessionList: ChatSession[]) => {
    const groups: { [key: string]: ChatSession[] } = {
      'Pinned': [],
      'Today': [],
      'Yesterday': [],
      'Last 7 Days': [],
      'Older': []
    };

    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const yesterday = new Date(now.getTime() - 86400000);
    const lastWeek = new Date(now.getTime() - 7 * 86400000);

    sessionList.forEach(s => {
      if (s.isPinned) {
        groups['Pinned'].push(s);
        return;
      }
      const d = new Date(s.timestamp_last_message);
      d.setHours(0, 0, 0, 0);

      if (d.getTime() === now.getTime()) groups['Today'].push(s);
      else if (d.getTime() === yesterday.getTime()) groups['Yesterday'].push(s);
      else if (d.getTime() >= lastWeek.getTime()) groups['Last 7 Days'].push(s);
      else groups['Older'].push(s);
    });

    return groups;
  };

  const grouped = groupSessions(filteredSessions);

  return (
    <div className="w-80 glass border-r border-cyan-500/20 flex flex-col h-full overflow-hidden shadow-2xl relative">
      {/* Search and Action Header */}
      <div className="p-4 border-b border-cyan-500/10 space-y-4 bg-black/20">
        <button 
          onClick={onNewChat}
          className="w-full flex items-center justify-center gap-2 py-3 bg-cyan-500/10 hover:bg-cyan-500/20 border border-cyan-500/40 rounded-lg text-cyan-400 font-orbitron text-[10px] tracking-widest transition-all group"
        >
          <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
          NEW_SESSION_UPLINK
        </button>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500" />
          <input 
            type="text"
            placeholder="Search archives..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-900/50 border border-white/5 rounded-md pl-10 pr-4 py-2 text-[11px] font-mono text-slate-300 focus:border-cyan-500/50 focus:outline-none transition-all"
          />
        </div>
      </div>

      {/* Session List */}
      <div className="flex-1 overflow-y-auto custom-scroll p-2 space-y-6">
        {Object.entries(grouped).map(([groupName, items]) => {
          if (items.length === 0) return null;
          return (
            <div key={groupName} className="space-y-1">
              <h3 className="px-3 text-[9px] font-orbitron text-slate-600 tracking-[0.2em] uppercase mb-2">
                {groupName}
              </h3>
              {items.map((session) => (
                <div 
                  key={session.session_id}
                  onClick={() => onSelectSession(session.session_id)}
                  className={`group relative p-3 rounded-lg cursor-pointer transition-all duration-300 border ${
                    activeSessionId === session.session_id 
                      ? 'bg-cyan-500/10 border-cyan-500/40 shadow-[inset_0_0_15px_rgba(0,242,255,0.1)]' 
                      : 'border-transparent hover:bg-white/5'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <div className="flex items-center gap-2 overflow-hidden">
                      <MessageSquare className={`w-3.5 h-3.5 shrink-0 ${activeSessionId === session.session_id ? 'text-cyan-400' : 'text-slate-500'}`} />
                      <h4 className={`text-[11px] font-semibold truncate ${activeSessionId === session.session_id ? 'text-cyan-400' : 'text-slate-200'}`}>
                        {session.title}
                      </h4>
                    </div>
                    {session.isPinned && <Pin className="w-3 h-3 text-cyan-500 shrink-0" />}
                  </div>

                  <p className="text-[10px] text-slate-500 font-mono line-clamp-1 mb-2">
                    {session.last_message_preview}
                  </p>

                  <div className="flex items-center justify-between text-[8px] font-mono text-slate-600">
                    <div className="flex items-center gap-3">
                      <span className="flex items-center gap-1 uppercase">
                        <Box className="w-2.5 h-2.5" /> {session.mode}
                      </span>
                      <span className="flex items-center gap-1">
                        <Cpu className="w-2.5 h-2.5" /> {session.messageCount} MSG
                      </span>
                      {session.memorySaved && (
                        <span className="text-emerald-500 flex items-center gap-1">
                          <Save className="w-2.5 h-2.5" /> MEM_STABLE
                        </span>
                      )}
                    </div>
                    <span>{new Date(session.timestamp_last_message).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>

                  {/* Actions Popover (Simulated) */}
                  <div className="absolute right-2 top-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                     <button className="p-1 hover:bg-white/10 rounded"><MoreVertical className="w-3 h-3 text-slate-400" /></button>
                  </div>
                </div>
              ))}
            </div>
          );
        })}

        {filteredSessions.length === 0 && (
          <div className="h-40 flex flex-col items-center justify-center text-slate-600 opacity-50">
             <History className="w-8 h-8 mb-2" />
             <span className="text-[9px] font-orbitron tracking-widest uppercase">Archive_Empty</span>
          </div>
        )}
      </div>

      {/* Panel Footer */}
      <div className="p-4 border-t border-cyan-500/10 bg-black/40">
        <div className="flex justify-between items-center px-2">
          <div className="flex flex-col">
            <span className="text-[8px] font-orbitron text-slate-500 tracking-tighter uppercase">Memory_Allocation</span>
            <div className="w-24 h-1 bg-slate-800 rounded-full mt-1 overflow-hidden">
               <div className="h-full bg-cyan-400 w-2/3 shadow-[0_0_5px_#00f2ff]" />
            </div>
          </div>
          <button className="p-2 hover:bg-white/5 rounded-full text-slate-500 hover:text-cyan-400 transition-colors">
            <Download className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

