    slate: 'text-slate-400 border-slate-500/30 bg-slate-500/5 hover:border-slate-300',
  };
  return (
    <button onClick={onClick} disabled={disabled} className={`group flex flex-col items-center gap-3 transition-all duration-300 transform hover:-translate-y-2 active:scale-95 ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}>
      <div className={`w-14 h-14 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${colorMap[color]} ${active ? 'shadow-[0_0_30px_rgba(0,242,255,0.4)] border-cyan-400 bg-cyan-500/20' : ''}`}>
