              <Paperclip className="w-4 h-4" />
              <span className="text-[8px] font-orbitron tracking-widest uppercase">Data</span>
            </button>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse" />
            <span className="text-[8px] font-mono text-cyan-500/50 uppercase tracking-tighter">Neural_Ready</span>
          </div>
        </div>

        {/* Hidden Inputs */}
        <input 
          type="file" 
          ref={imageInputRef} 
          hidden 
          accept="image/*" 
          multiple 
