  model: string;
  isPinned?: boolean;
  messageCount: number;
  memorySaved: boolean;
}

interface ChatHistoryPanelProps {
  isVisible: boolean;
  activeSessionId: string | null;
  onSelectSession: (id: string) => void;
  onNewChat: () => void;
  onSendMessage: (msg: string, files?: File[]) => void;
}

const ChatHistoryPanel: React.FC<ChatHistoryPanelProps> = ({ 
  isVisible, 
  activeSessionId, 
  onSelectSession, 
  onNewChat,
  onSendMessage 
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [inputValue, setInputValue] = useState('');
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  // Simulated sessions
  const [sessions, setSessions] = useState<ChatSession[]>([
    {
      session_id: 's1',
      title: 'Neural Core Optimization',
      timestamp_created: Date.now() - 3600000,
      timestamp_last_message: Date.now() - 600000,
      last_message_preview: "Sir, I have recalibrated the thermal sensors in Sector 4.",
      mode: 'DEVELOPER',
      model: 'gemini-2.5-flash',
      isPinned: true,
      messageCount: 42,
      memorySaved: true
    },
    {
      session_id: 's2',
      title: 'Project Mark-III Schematics',
      timestamp_created: Date.now() - 86400000,
      timestamp_last_message: Date.now() - 86400000 + 3600000,
      last_message_preview: "Analyzing the 3D model for the new HUD overlay...",
      mode: 'WORK',
      model: 'gemini-2.5-pro',
      messageCount: 15,
      memorySaved: true
    }
  ]);

  const filteredSessions = useMemo(() => {
    return sessions.filter(s => 
      s.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.last_message_preview.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [sessions, searchQuery]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: ChatSession[] } = { 'Pinned': [], 'Today': [], 'Older': [] };
    filteredSessions.forEach(s => {
      if (s.isPinned) groups['Pinned'].push(s);
      else if (new Date(s.timestamp_last_message).toDateString() === new Date().toDateString()) groups['Today'].push(s);
      else groups['Older'].push(s);
    });
    return groups;
  }, [filteredSessions]);

  const handleSend = () => {
    if (inputValue.trim() || selectedFiles.length > 0) {
      onSendMessage(inputValue, selectedFiles);
      setInputValue('');
      setSelectedFiles([]);
    }
  };

  const removeFile = (index: number) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  if (!isVisible) return null;

  return (
    <div className="w-80 glass border-r border-cyan-500/20 flex flex-col h-full overflow-hidden shadow-2xl relative animate-in slide-in-from-left duration-500">
      {/* Search and Action Header */}
      <div className="p-4 border-b border-cyan-500/10 space-y-4 bg-black/20">
        <button 
          onClick={onNewChat}
          className="w-full flex items-center justify-center gap-2 py-3 bg-cyan-500/10 hover:bg-cyan-500/20 border border-cyan-500/40 rounded-lg text-cyan-400 font-orbitron text-[10px] tracking-widest transition-all group"
        >
          <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
          NEW_SESSION_UPLINK
        </button>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500" />
          <input 
            type="text"
            placeholder="Search archives..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-900/50 border border-white/5 rounded-md pl-10 pr-4 py-2 text-[11px] font-mono text-slate-300 focus:border-cyan-500/50 focus:outline-none transition-all"
          />
        </div>
      </div>

      {/* Session List */}
      <div className="flex-1 overflow-y-auto custom-scroll p-2 space-y-6">
        {/* Fix: Explicitly cast Object.entries to ensure 'items' is inferred as ChatSession[] to resolve 'unknown' property errors */}
        {(Object.entries(grouped) as [string, ChatSession[]][]).map(([groupName, items]) => {
          if (items.length === 0) return null;
          return (
            <div key={groupName} className="space-y-1">
              <h3 className="px-3 text-[9px] font-orbitron text-slate-600 tracking-[0.2em] uppercase mb-2">
                {groupName}
              </h3>
              {items.map((session) => (
                <div 
                  key={session.session_id}
                  onClick={() => onSelectSession(session.session_id)}
                  className={`group relative p-3 rounded-lg cursor-pointer transition-all duration-300 border ${
                    activeSessionId === session.session_id 
                      ? 'bg-cyan-500/10 border-cyan-500/40 shadow-[inset_0_0_15px_rgba(0,242,255,0.1)]' 
                      : 'border-transparent hover:bg-white/5'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <div className="flex items-center gap-2 overflow-hidden">
                      <MessageSquare className={`w-3.5 h-3.5 shrink-0 ${activeSessionId === session.session_id ? 'text-cyan-400' : 'text-slate-500'}`} />
                      <h4 className={`text-[11px] font-semibold truncate ${activeSessionId === session.session_id ? 'text-cyan-400' : 'text-slate-200'}`}>
                        {session.title}
                      </h4>
                    </div>
                  </div>
                  <p className="text-[10px] text-slate-500 font-mono line-clamp-1 mb-2">
                    {session.last_message_preview}
                  </p>
                  <div className="flex items-center justify-between text-[8px] font-mono text-slate-600">
                    <span className="uppercase">{session.mode}</span>
                    <span>{new Date(session.timestamp_last_message).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                </div>
              ))}
            </div>
          );
        })}
      </div>

      {/* TACTICAL CHATBOX (BOTTOM SECTION) */}
      <div className="p-4 border-t border-cyan-500/20 bg-slate-950/80 backdrop-blur-xl">
        {selectedFiles.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-3 max-h-24 overflow-y-auto custom-scroll p-1">
            {selectedFiles.map((f, i) => (
              <div key={i} className="flex items-center gap-2 px-2 py-1 bg-cyan-500/10 border border-cyan-500/30 rounded text-[9px] text-cyan-400 font-mono">
                <span className="truncate max-w-[100px]">{f.name}</span>
                <button onClick={() => removeFile(i)} className="hover:text-red-400 transition-colors"><X className="w-3 h-3" /></button>
              </div>
            ))}
          </div>
        )}

        <div className="relative group">
          <textarea
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
            placeholder="Type your command, Sir..."
            className="w-full bg-black/40 border border-cyan-500/20 rounded-xl pl-4 pr-12 py-3 text-sm font-sans text-slate-200 focus:border-cyan-500/50 focus:outline-none transition-all resize-none min-h-[50px] max-h-[150px] custom-scroll"
          />
          <button 
            onClick={handleSend}
            disabled={!inputValue.trim() && selectedFiles.length === 0}
            className="absolute right-2 bottom-2 p-2 rounded-lg bg-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>

        <div className="flex items-center justify-between mt-3 px-1">
          <div className="flex gap-4">
            <button 
              onClick={() => imageInputRef.current?.click()}
              className="text-slate-500 hover:text-cyan-400 transition-colors flex items-center gap-1.5"
            >
              <ImageIcon className="w-4 h-4" />
              <span className="text-[8px] font-orbitron tracking-widest uppercase">Optics</span>
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="text-slate-500 hover:text-cyan-400 transition-colors flex items-center gap-1.5"
            >
              <Paperclip className="w-4 h-4" />
              <span className="text-[8px] font-orbitron tracking-widest uppercase">Data</span>
            </button>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse" />
            <span className="text-[8px] font-mono text-cyan-500/50 uppercase tracking-tighter">Neural_Ready</span>
          </div>
        </div>

        {/* Hidden Inputs */}
        <input 
          type="file" 
          ref={imageInputRef} 
          hidden 
          accept="image/*" 
          multiple 
          onChange={(e) => e.target.files && setSelectedFiles(prev => [...prev, ...Array.from(e.target.files!)])} 
        />
        <input 
          type="file" 
          ref={fileInputRef} 
          hidden 
          multiple 
          onChange={(e) => e.target.files && setSelectedFiles(prev => [...prev, ...Array.from(e.target.files!)])} 
        />
      </div>
    </div>
  );
};

