  model: string;
  isPinned?: boolean;
  messageCount: number;
  memorySaved: boolean;
}

interface ChatHistoryPanelProps {
  isVisible: boolean;
  activeSessionId: string | null;
  onSelectSession: (id: string) => void;
  onNewChat: () => void;
}

const ChatHistoryPanel: React.FC<ChatHistoryPanelProps> = ({ 
  isVisible, 
  activeSessionId, 
  onSelectSession, 
  onNewChat
}) => {
  const [searchQuery, setSearchQuery] = useState('');

  const [sessions] = useState<ChatSession[]>([
    {
      session_id: 's1',
      title: 'Neural Core Optimization',
      timestamp_created: Date.now() - 3600000,
      timestamp_last_message: Date.now() - 600000,
      last_message_preview: "Sir, I have recalibrated the thermal sensors in Sector 4.",
      mode: 'DEVELOPER',
      model: 'gemini-2.5-flash',
      isPinned: true,
      messageCount: 42,
      memorySaved: true
    },
    {
      session_id: 's2',
      title: 'Project Mark-III Schematics',
      timestamp_created: Date.now() - 86400000,
      timestamp_last_message: Date.now() - 86400000 + 3600000,
      last_message_preview: "Analyzing the 3D model for the new HUD overlay...",
      mode: 'WORK',
      model: 'gemini-2.5-pro',
      messageCount: 15,
      memorySaved: true
    }
  ]);

  const filteredSessions = useMemo(() => {
    return sessions.filter(s => 
      s.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.last_message_preview.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [sessions, searchQuery]);

  const grouped = useMemo(() => {
    const groups: { [key: string]: ChatSession[] } = { 'Pinned': [], 'Today': [], 'Older': [] };
    filteredSessions.forEach(s => {
      if (s.isPinned) groups['Pinned'].push(s);
      else if (new Date(s.timestamp_last_message).toDateString() === new Date().toDateString()) groups['Today'].push(s);
      else groups['Older'].push(s);
    });
    return groups;
  }, [filteredSessions]);

  if (!isVisible) return null;

  return (
    <div className="w-80 glass border-r border-cyan-500/20 flex flex-col h-full overflow-hidden shadow-2xl relative animate-in slide-in-from-left duration-500 z-40">
      <div className="p-4 border-b border-cyan-500/10 space-y-4 bg-black/20">
        <button 
          onClick={onNewChat}
          className="w-full flex items-center justify-center gap-2 py-3 bg-cyan-500/10 hover:bg-cyan-500/20 border border-cyan-500/40 rounded-lg text-cyan-400 font-orbitron text-[10px] tracking-widest transition-all group"
        >
          <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
          NEW_SESSION
